void ui_charging_screen_init(void)
{
    s_charge_dsc = app_img_load_raw("/spiffs/usr/share/watchfaces/ui_img_charge_png.bin",
                                    128, 128, LV_COLOR_FORMAT_NATIVE_WITH_ALPHA);

    /* CRITICAL: create the charging overlay as a child of the TOP LAYER,
     * not as a screen.  A screen (lv_obj_create(NULL)) has parent == NULL,
     * and LVGL 9.3 refuses to reparent screens — lv_obj_set_parent() warns
     * "Can't set the parent of a screen" and does nothing.  A floating
     * overlay built as a screen therefore NEVER RENDERS.  Creating it under
     * lv_layer_top() makes it a normal object that draws above the active
     * screen, which is exactly what the charging overlay needs. */
    ui_charging = lv_obj_create(lv_layer_top());
    lv_obj_remove_flag(ui_charging, LV_OBJ_FLAG_SCROLLABLE);      /// Flags
    lv_obj_set_style_bg_color(ui_charging, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(ui_charging, 255, LV_PART_MAIN | LV_STATE_DEFAULT);

    ui_Image3 = lv_image_create(ui_charging);
    if (s_charge_dsc) lv_image_set_src(ui_Image3, s_charge_dsc);
    else              lv_obj_add_flag(ui_Image3, LV_OBJ_FLAG_HIDDEN);
    lv_obj_set_width(ui_Image3, LV_SIZE_CONTENT);   /// 1
    lv_obj_set_height(ui_Image3, LV_SIZE_CONTENT);    /// 1
    lv_obj_set_align(ui_Image3, LV_ALIGN_CENTER);
    lv_obj_add_flag(ui_Image3, LV_OBJ_FLAG_CLICKABLE);     /// Flags
    lv_obj_remove_flag(ui_Image3, LV_OBJ_FLAG_SCROLLABLE);      /// Flags

    ui_charge = lv_arc_create(ui_charging);
    lv_obj_set_width(ui_charge, 240);
    lv_obj_set_height(ui_charge, 240);
    lv_obj_set_align(ui_charge, LV_ALIGN_CENTER);
    lv_obj_remove_flag(ui_charge, LV_OBJ_FLAG_CLICKABLE);  /* read-only */
    lv_arc_set_value(ui_charge, 0);
    lv_arc_set_bg_angles(ui_charge, 270, 629);
    lv_obj_set_style_arc_color(ui_charge, lv_color_hex(0xB4B4B4), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_opa(ui_charge, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_width(ui_charge, 20, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_rounded(ui_charge, true, LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_set_style_arc_color(ui_charge, lv_color_hex(0x39FF00), LV_PART_INDICATOR | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_opa(ui_charge, 255, LV_PART_INDICATOR | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_width(ui_charge, 20, LV_PART_INDICATOR | LV_STATE_DEFAULT);
    lv_obj_set_style_arc_rounded(ui_charge, true, LV_PART_INDICATOR | LV_STATE_DEFAULT);

    lv_obj_set_style_opa(ui_charge, 0, LV_PART_KNOB | LV_STATE_DEFAULT);

    /* The overlay starts HIDDEN — app_ui shows + fades it in when charging
     * starts.  It is read-only, so touches pass through to the watch face. */
    lv_obj_add_flag(ui_charging, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(ui_charging, LV_OBJ_FLAG_CLICKABLE);
}

